import json
import os
import sys

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts_by_rule = manifest["facts"]

    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    with open(awards_path) as f:
        awards = json.load(f)

    records_by_id = {}
    for record in awards:
        uid = record.get("generated_unique_award_id")
        if uid is not None:
            records_by_id.setdefault(uid, []).append(record)

    def format_amount(v):
        if isinstance(v, bool):
            return None
        if isinstance(v, (int, float)):
            return f"{v:.2f}"
        return str(v)

    def get_performance_start(record):
        pop = record.get("period_of_performance") or {}
        v = pop.get("start_date")
        if not v:
            return None
        return v

    def get_performance_end(record):
        pop = record.get("period_of_performance") or {}
        v = pop.get("end_date")
        if not v:
            return None
        return v

    def get_amount_obligated(record):
        v = record.get("total_obligation")
        if v is None:
            return None
        return format_amount(v)

    def get_potential_value(record):
        v = record.get("base_and_all_options")
        if v is None:
            return None
        return format_amount(v)

    fact_extractors = {
        "usa.period_3y": {
            "performance start": get_performance_start,
            "performance end": get_performance_end,
        },
        "usa.obligated_95": {
            "amount obligated": get_amount_obligated,
            "potential value": get_potential_value,
        },
    }

    result = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])
        extractors = fact_extractors.get(rule_id, {})

        matching_records = records_by_id.get(entity, [])

        fact_results = {}
        for fact_name in fact_names:
            extractor = extractors.get(fact_name)
            if extractor is None:
                fact_results[fact_name] = "ABSENT"
                continue

            values = []
            for record in matching_records:
                v = extractor(record)
                if v is not None:
                    values.append(v)

            if len(values) == 0:
                fact_results[fact_name] = "ABSENT"
            else:
                unique_values = list(dict.fromkeys(values))
                if len(unique_values) == 1:
                    fact_results[fact_name] = [unique_values[0], "usaspending_awards"]
                else:
                    fact_results[fact_name] = "CONFLICT"

        result[pair] = fact_results

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()
