import json
import os
import sys

def load_records(packet_dir, manifest_path):
    manifest_abspath = os.path.abspath(manifest_path)
    records_by_doc = {}
    for filename in os.listdir(packet_dir):
        if filename.endswith('.json'):
            filepath = os.path.join(packet_dir, filename)
            if os.path.abspath(filepath) == manifest_abspath:
                continue
            doc_name = os.path.splitext(filename)[0]
            with open(filepath, 'r') as f:
                data = json.load(f)
            if isinstance(data, list):
                records_by_doc[doc_name] = data
            else:
                records_by_doc[doc_name] = [data]
    return records_by_doc

def get_field_value(record, fact_name, rule_id):
    if rule_id == 'usa.period_3y':
        pop = record.get('period_of_performance') or {}
        if fact_name == 'performance start':
            return pop.get('start_date')
        elif fact_name == 'performance end':
            return pop.get('end_date')
    elif rule_id == 'usa.obligated_95':
        if fact_name == 'amount obligated':
            return record.get('total_obligation')
        elif fact_name == 'potential value':
            return record.get('base_and_all_options')
    return None

def format_value(value, fact_name, rule_id):
    if rule_id == 'usa.obligated_95':
        if isinstance(value, int) and not isinstance(value, bool):
            return str(value) + '.00'
        return str(value)
    else:
        return value

def main():
