from decimal import Decimal

def load_records(packet_dir):
    records_by_entity = {}

    for filename in os.listdir(packet_dir):
        if filename.endswith('.json'):
            filepath = os.path.join(packet_dir, filename)
            doc_name = filename[:-5]

            with open(filepath, 'r') as f:
                data = json.load(f)

            if isinstance(data, list):
                for record in data:
                    entity_id = record.get('generated_unique_award_id')
                    if entity_id:
                        records_by_entity.setdefault(entity_id, []).append((record, doc_name))
            elif isinstance(data, dict):
                entity_id = data.get('generated_unique_award_id')
                if entity_id:
                    records_by_entity.setdefault(entity_id, []).append((data, doc_name))

    return records_by_entity

def extract_field(record, field_path):
    parts = field_path.split('.')
    value = record
    for part in parts:
        if isinstance(value, dict):
            value = value.get(part)
        else:
            return None
    return value

def format_value(value, rule_id):
    if value is None:
        return None

    if rule_id == 'usa.period_3y':
        if isinstance(value, str):
            return value.split(' ')[0] if ' ' in value else value
        return str(value)
    elif rule_id == 'usa.obligated_95':
        if isinstance(value, (int, float)):
            return str(Decimal(str(value)))
        return str(value)

    return str(value)

def get_field_path(rule_id, fact_name):
    if rule_id == 'usa.period_3y':
        if fact_name == 'performance start':
            return 'period_of_performance.start_date'
        elif fact_name == 'performance end':
            return 'period_of_performance.end_date'
    elif rule_id == 'usa.obligated_95':
        if fact_name == 'amount obligated':
            return 'total_obligation'
        elif fact_name == 'potential value':
