Looking at this problem, I need to:
1. Read the manifest to get pairs (rule_id::entity) and facts per rule
2. Load `usaspending_awards.json` and index awards by `generated_unique_award_id`
3. For each pair, extract the relevant fields based on the rule
4. Handle ABSENT (null/missing) and CONFLICT (disagreeing values across matching records)
5. Format dates as YYYY-MM-DD and amounts as decimal strings

Key observations:
- Entity in manifest = `generated_unique_award_id` field in awards
- `usa.period_3y` facts come from `period_of_performance.start_date` and `period_of_performance.end_date`
- `usa.obligated_95` facts come from `total_obligation` and `base_and_all_options`
- Some values are null (e.g., start_date for some awards, base_and_all_options for one award) → ABSENT
- Document name is the filename without extension: `usaspending_awards`

```python
import json
import os
import sys
from decimal import Decimal

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    awards = []
    if os.path.exists(awards_path):
        with open(awards_path) as f:
            awards = json.load(f)

    awards_by_id = {}
    for award in awards:
        gid = award.get("generated_unique_award_id")
        if gid:
            awards_by_id.setdefault(gid, []).append(award)

    result = {}

    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"].get(rule_id, [])

        matching_awards = awards_by_id.get(entity, [])

        fact_results = {}
        for fact in facts:
            values = []
            for award in matching_awards:
                val = extract_fact(rule_id, fact, award)
                if val is not None:
                    values.append((val, "usaspending_awards"))

            if not values:
                fact_results[fact] = "ABSENT"
            else:
                distinct_values = set(v for v, d in values)
                if len(distinct_values) == 1:
                    v, d = values[0]
                    fact_results[fact] = [v, d]
                else:
                    fact_results[fact] = "CONFLICT"

        result[pair] = fact_results

    print(json.dumps(result))

def extract_fact(rule_id, fact, award):
    if rule_id == "usa.period_3y":
        pop = award.get("period_of_performance") or {}
        if fact == "performance start":
            val = pop.get("start_date")
            if val is None or val == "":
                return None
            return val
        elif fact == "performance end":
            val = pop.get("end_date")
            if val is None or val == "":
                return None
            return val
    elif rule_id == "usa.obligated_95":
        if fact == "amount obligated":
            val = award.get("total_obligation")
            if val is None:
                return None
            return format_amount(val)
        elif fact == "potential value":
            val = award.get("base_and_all_options")
            if val is None:
                return None
            return format_amount(val)
    return None

def format_amount(val):
    if isinstance(val, (int, float)):
        return str(Decimal(str(val)))
    return str(val)

if __name__ == "__main__":
    main()
